<h1>Siparişlerim</h1><section class="card"><?php if(!$orders):?><p>Henüz siparişiniz bulunmuyor.</p><?php endif?><?php foreach($orders as $o):?><div class="line"><b>#<?=$o['id']?> · <?=e($o['service'])?></b><p>Miktar: <?=$o['quantity']?> · Tutar: <?=money($o['charge'])?> · Durum: <strong><?=e(order_status_label($o['status']))?></strong></p><p><small><?=e($o['created_at'])?></small></p><?php if(!empty($o['provider_order_id'])):?><small>Sağlayıcı sipariş no: <?=e($o['provider_order_id'])?></small><?php endif?><?php if($o['status']==='manual_review'):?><p><small>Siparişiniz yönetici tarafından işleme alınacaktır.</small></p><?php endif?></div><?php endforeach?></section>